{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that all specified fields are captured."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct colors for the four triage categories are verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting valid and invalid vital sign values to observe correct recording and rejection behavior."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by disabling network connectivity and creating 500 records to ensure the application remains functional and stores them locally."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by simulating conflicting edits, restoring connectivity, and observing the synchronization and conflict resolution process."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration to confirm the correct algorithm is implemented."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The operability with surgical gloves is verified by a user wearing gloves interacting with the tablet interface to demonstrate usability."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The battery life requirement is verified by running the application under the defined usage profile and measuring the duration until battery depletion."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by submitting documents and observing that the system returns exactly one category and a valid confidence score."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score requires statistical analysis of the model's performance on the held-out evaluation set."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing behavior for low-confidence documents is verified by submitting documents with scores below 0.60 and observing their placement in the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing a load test at 50 requests per second and measuring the response time percentiles."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "Test"
      ],
      "rationale": "The logging functionality is verified by sending requests and checking the system logs for the presence of model version, input hash, and predicted category."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting distribution deviation using the population stability index requires statistical analysis of the weekly predicted category data against the baseline."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The provision of top contributing text passages is verified by submitting a document and inspecting the response payload for the three specified passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between Turkish and English documents requires statistical analysis of the model's performance on separate language-specific test sets."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin 1 saniye sınırına uyup uymadığı, sisteme girdi verilerek ve çıktı gözlemlenerek ölçülebilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "2.000 iz yükü altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı, sistem çalıştırılarak ve performans ölçümü yapılarak doğrulanabilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını (kimlik, hız, yön, zaman) ekranda görebilmesi, işlevin çalıştırılıp gözlemlenmesiyle gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "30 saniyede 'eskimiş' işareti ve 120 saniyede kaldırma davranışının zamanlaması, sistem çalıştırılarak ve süreler ölçülerek test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye giriş durumunda görsel ve sesli uyarının tetiklenip tetiklenmediği, senaryo çalıştırılarak ve çıktı gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj iletim süresinin 2 saniye sınırına uyumu ve durum bildiriminin gösterimi, mesaj gönderilerek ve sonuç gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Kayıtların zaman damgası ve kullanıcı kimliği içermesi ile değiştirilemezlik özelliği, log dosyalarının ve yapılandırmanın gözle denetlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Sunucu arızası durumunda devralma süresinin 10 saniye içinde gerçekleşmesi ve veri bütünlüğünün korunması, arıza senaryosu çalıştırılarak test edilebilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılarak doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme girdi verilerek ve sonuç gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının uygulanıp uygulanmadığı, farklı senaryolarla sisteme dosya yüklenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz numara üretimi ve e-posta gönderimi, sistemin çalıştırılması ve çıktıların gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevi, sisteme veri girilip bekletildikten sonra erişim denemesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzünün kod yapısı, HTML semantiği ve erişilebilirlik araçlarıyla üretilen raporların gözle denetlenmesiyle doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma dosyaları ve sunucu konum bilgileri incelenerek doğrulanabilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, kontrollü istek yükü uygulanarak sistemin davranışının gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında 99. yüzdelik gecikme metrikinin karşılanıp karşılanmadığının belirlenmesi, performans testleri sonucunda elde edilen verilerin istatistiksel analizi gerektirir."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç zaman aşımı durumunda isteğin sonlandırılması ve HTTP 504 yanıtının, arka uç servisin gecikmeli yanıt vermesi simüle edilerek sistemin davranışının gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve aktif istekleri düşürmeden uygulanmasının, sistem çalışırken yapılandırma güncellenerek gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin kaydedilmesi ve günlük dosyasında gerekli alanların (izleme kimliği, süre vb.) bulunup bulunmadığının, istekler gönderildikten sonra günlük çıktısının incelenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, sistemden toplanan çalışma ve kesinti sürelerinin istatistiksel analizi gerektirdiğinden analiz yöntemi uygundur."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and running on the tablet. A test casualty record is available to be created.",
      "test_inputs": "Test casualty data (e.g., Name: 'Test Patient', ID: '12345').",
      "assumptions": "Access to the device's file system or storage dump is available for inspection.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record in the application with the test data.",
          "expected": "The casualty record is successfully saved and visible in the application."
        },
        {
          "no": 2,
          "action": "Access the underlying storage file or database where the casualty data is persisted.",
          "expected": "The raw data is not readable as plain text."
        },
        {
          "no": 3,
          "action": "Analyze the encryption metadata or key usage logs associated with the stored data.",
          "expected": "The data is confirmed to be encrypted using the AES-256 algorithm."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100%). The 'defined usage profile' is documented and available for execution.",
      "test_inputs": "Defined usage profile script or manual procedure.",
      "assumptions": "The 'defined usage profile' involves continuous operation of the application with typical triage activities (data entry, viewing records) for the duration of the test.",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with the application running and begin the defined usage profile.",
          "expected": "The application is operational and the battery level is recorded as 100%."
        },
        {
          "no": 2,
          "action": "Continue the defined usage profile until the tablet battery is depleted or the device shuts down.",
          "expected": "The tablet remains operational and the application is responsive throughout the test."
        },
        {
          "no": 3,
          "action": "Record the total elapsed time from the start of the test until the device shuts down or becomes unusable.",
          "expected": "The total elapsed time is at least 8 hours."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation dataset is available and accessible.",
      "test_inputs": "Held-out evaluation dataset containing labeled documents.",
      "assumptions": "The evaluation script correctly calculates the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation dataset.",
          "expected": "The model generates predictions for all documents in the dataset."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score by comparing predictions with ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation dataset containing both Turkish and English documents is available.",
      "test_inputs": "Held-out evaluation dataset split into Turkish and English subsets.",
      "assumptions": "The evaluation script correctly calculates recall for each language subset.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the Turkish subset of the held-out evaluation dataset.",
          "expected": "The model generates predictions for all Turkish documents."
        },
        {
          "no": 2,
          "action": "Calculate the recall score for the Turkish subset.",
          "expected": "A recall value for Turkish documents is obtained."
        },
        {
          "no": 3,
          "action": "Run the classification model on the English subset of the held-out evaluation dataset.",
          "expected": "The model generates predictions for all English documents."
        },
        {
          "no": 4,
          "action": "Calculate the recall score for the English subset.",
          "expected": "A recall value for English documents is obtained."
        },
        {
          "no": 5,
          "action": "Calculate the absolute difference between the Turkish and English recall scores.",
          "expected": "The difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Kullanıcı arayüzünün WCAG 2.1 AA uyumluluğunun doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem test ortamında çalışmaktadır ve tarayıcıda erişilebilirlik eklentileri (ör. Lighthouse, axe-core) yüklüdür.",
      "test_inputs": "Portalın ana sayfası ve temel işlevsellik sayfaları (giriş, başvuru formu).",
      "assumptions": "WCAG 2.1 AA kriterleri için otomatik test araçlarının %100 doğruluk sağlamadığı, ancak temel yapısal hataları yakalayabildiği kabul edilir.",
      "steps": [
        {
          "no": 1,
          "action": "Tarayıcıda erişilebilirlik test aracı (ör. Lighthouse) kullanılarak portalın ana sayfası taranır.",
          "expected": "Rapor, WCAG 2.1 AA kriterleri için kritik hata (critical error) içermemeli ve erişilebilirlik skoru AA eşik değerini karşılamalıdır."
        },
        {
          "no": 2,
          "action": "Klavye navigasyonu kullanılarak sayfadaki tüm etkileşimli öğelere (butonlar, giriş alanları, menüler) sırayla erişilir.",
          "expected": "Tüm etkileşimli öğeler klavye ile odaklanabilir ve kullanılabilir olmalı; odak göstergesi (focus indicator) görünür olmalıdır."
        },
        {
          "no": 3,
          "action": "Ekran okuyucu (ör. NVDA veya JAWS) etkinleştirilerek sayfa içeriği dinlenir.",
          "expected": "Başlıklar, form etiketleri ve butonlar doğru semantik yapılarla okunmalı; görsel öğeler için uygun alternatif metinler (alt text) sağlanmalıdır."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Erişim belirteci olmadan istek gönderimi",
      "covers": [
        "SW-001"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Ağ geçidi çalışmaktadır ve hedef uç nokta erişilebilir durumdadır.",
      "test_inputs": "Authorization başlığı içermeyen HTTP GET isteği.",
