{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Offline functionality and local storage capacity",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and configured. Network connectivity is disabled (airplane mode or disconnected).",
      "test_inputs": "500 unique casualty record data sets.",
      "assumptions": "The application allows manual creation of casualty records. The 'fully functional' scope includes creating, viewing, and editing records.",
      "steps": [
        {
          "no": 1,
          "action": "Create 500 distinct casualty records in the application while offline.",
          "expected": "All 500 records are successfully saved to local storage without errors."
        },
        {
          "no": 2,
          "action": "Attempt to view, edit, and delete a sample of the created records.",
          "expected": "The application responds correctly to all operations, confirming full functionality without network."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Local storage boundary: 500 records",
      "covers": [
        "MED-004"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "The application is offline. Local storage is empty.",
      "test_inputs": "500 casualty record data sets.",
      "assumptions": "The requirement specifies 'at least 500', so the 500th record must be accepted.",
      "steps": [
        {
          "no": 1,
          "action": "Create 499 casualty records.",
          "expected": "All 499 records are saved successfully."
        },
        {
          "no": 2,
          "action": "Create the 500th casualty record.",
          "expected": "The 500th record is saved successfully, meeting the minimum capacity requirement."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Synchronization upon connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is offline. 10 local casualty records have been created. The server is accessible and has no conflicting records for these IDs.",
      "test_inputs": "10 local casualty records.",
      "assumptions": "The application automatically detects connectivity restoration and initiates sync.",
      "steps": [
        {
          "no": 1,
          "action": "Restore network connectivity.",
          "expected": "The application initiates synchronization with the server."
        },
        {
          "no": 2,
          "action": "Wait for synchronization to complete.",
          "expected": "The 10 local records are successfully uploaded to the server. The local status of these records is updated to 'synced'."
        }
      ]
    },
    {
      "id": "TC-004",
      "title": "Conflict resolution: Keep both versions for manual review",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
